import os
import random
import string
from io import BytesIO
from tempfile import mkstemp
from django.core.files.storage import default_storage
from django.core.exceptions import ObjectDoesNotExist
from PIL import Image, ImageDraw, ImageFont, ImageFilter

class CaptchaStore:
    def __init__(self, challenge_length=6):
        self.challenge_key = self._generate_key()
        self.challenge_text = self._generate_challenge_text(challenge_length)
        self.image_format = 'PNG'

    def _generate_key(self):
        return ''.join(random.choices(string.ascii_letters + string.digits, k=16))

    def _generate_challenge_text(self, length):
        return ''.join(random.choices(string.ascii_uppercase + string.digits, k=length))

    def generate_image_challenge(self, width=300, height=100):
        image = Image.new('RGB', (width, height), color='white')
        draw = ImageDraw.Draw(image)
        font_path = self._select_random_font()
        font_size = random.randint(40, 60)
        font = ImageFont.truetype(font_path, font_size)

        # Add background noise
        for _ in range(random.randint(50, 100)):
            x = random.randint(0, width)
            y = random.randint(0, height)
            draw.point((x, y), fill=self._random_noise_color())

        # Render challenge text with transformations
        text_width, text_height = draw.textsize(self.challenge_text, font=font)
        x = (width - text_width) // 2
        y = (height - text_height) // 2

        for i, char in enumerate(self.challenge_text):
            char_image = Image.new('RGBA', (width, height), (255, 255, 255, 0))
            char_draw = ImageDraw.Draw(char_image)
            char_draw.text((x + i * text_width // len(self.challenge_text), y), 
                           char, font=font, fill=self._random_text_color())

            # Apply random rotation
            rotated_char = char_image.rotate(random.randint(-30, 30), 
                                             expand=False, 
                                             fillcolor=(255, 255, 255, 0))
            image.paste(rotated_char, (0, 0), rotated_char)

        # Apply additional filters
        image = image.filter(ImageFilter.EDGE_ENHANCE)
        image = image.filter(ImageFilter.SMOOTH)

        return image

    def _select_random_font(self):
        font_directory = '/path/to/fonts'
        fonts = [os.path.join(font_directory, f) for f in os.listdir(font_directory) if f.endswith(('.ttf', '.otf'))]
        return random.choice(fonts)

    def _random_text_color(self):
        return (random.randint(0, 100), random.randint(0, 100), random.randint(0, 100))

    def _random_noise_color(self):
        return (random.randint(150, 255), random.randint(150, 255), random.randint(150, 255))

    def generate_audio_challenge(self):
        # Placeholder for audio generation logic
        pass

    def verify_challenge(self, user_input):
        return user_input.upper() == self.challenge_text

def captcha_image(request, challenge_key=None):
    try:
        captcha = CaptchaStore(challenge_key) if challenge_key else CaptchaStore()
        image = captcha.generate_image_challenge()

        response_image = BytesIO()
        image.save(response_image, format='PNG')
        response_image.seek(0)

        return HttpResponse(response_image.read(), content_type='image/png')
    except Exception as e:
        return HttpResponse(f"Error generating CAPTCHA: {str(e)}", status=500)

import os
import xml.sax
import xml.etree.ElementTree as ET
import logging

class ProviderXMLHandler(xml.sax.ContentHandler):
    def __init__(self):
        self.current_tag = ""
        self.providers = []
        self.current_provider = {}
        self.current_server = {}
        self.debug = False

    def startElement(self, name, attrs):
        self.current_tag = name

        if name == "provider":
            self.current_provider = {
                "name": attrs.get("name", ""),
                "domains": [],
                "servers": []
            }

        if name == "server":
            self.current_server = {
                "type": attrs.get("type", ""),
                "hostname": "",
                "port": "",
                "socket_type": "",
                "authentication": ""
            }

    def characters(self, content):
        content = content.strip()

        if not content:
            return

        if self.current_tag == "domain":
            self.current_provider["domains"].append(content)

        if self.current_tag == "hostname":
            self.current_server["hostname"] = content

        if self.current_tag == "port":
            self.current_server["port"] = content

        if self.current_tag == "socket_type":
            self.current_server["socket_type"] = content

        if self.current_tag == "authentication":
            self.current_server["authentication"] = content

    def endElement(self, name):
        if name == "server":
            self.current_provider["servers"].append(self.current_server)
            self.current_server = {}

        if name == "provider":
            self.providers.append(self.current_provider)
            self.current_provider = {}

        self.current_tag = ""

def getProviders(xml_dir, debug=False):
    parser = xml.sax.make_parser()
    handler = ProviderXMLHandler()
    handler.debug = debug
    parser.setContentHandler(handler)

    providers = []
    for filename in os.listdir(xml_dir):
        if filename.endswith(".xml"):
            try:
                parser.parse(os.path.join(xml_dir, filename))
                providers.extend(handler.providers)
            except Exception as e:
                if debug:
                    logging.error(f"Error parsing {filename}: {e}")

    return providers

def getProviderFromFilenames(providers, email):
    domain = email.split('@')[-1]

    for provider in providers:
        if domain in provider['domains']:
            return provider

    return None

def printl(message, debug=False):
    if debug:
        print(message)

def main():
    debug = True
    currentPath = os.path.dirname(os.path.abspath(__file__))
    xmlPath = os.path.join(currentPath, 'xml')

    providers = getProviders(xmlPath, debug)
    printl(f"Loaded {len(providers)} providers", debug)

    test_emails = [
        'user@gmail.com', 
        'support@yahoo.com', 
        'contact@outlook.com'
    ]

    for email in test_emails:
        provider = getProviderFromFilenames(providers, email)
        if provider:
            printl(f"Email: {email}", debug)
            printl(f"Provider: {provider['name']}", debug)
            for server in provider['servers']:
                printl(f"Server: {server['type']} - {server['hostname']}:{server['port']}", debug)
        else:
            printl(f"No provider found for {email}", debug)

if __name__ == "__main__":
    main()

import unittest
import mock
from ganeti.errors import _SetupError
from ganeti.constants import NDS_SSCONF, SS_CLUSTER_NAME, SS_INSTANCE_LIST
from ganeti.tools import node_daemon_setup
from testutils import testutils

class TestVerifySsconf(unittest.TestCase):
    def setUp(self):
        self.valid_ssconf = {
            NDS_SSCONF: {
                SS_CLUSTER_NAME: "test-cluster",
                SS_INSTANCE_LIST: ["instance1", "instance2"]
            }
        }

    def _Check(self, ssconf, expected_error=None):
        if expected_error is None:
            try:
                node_daemon_setup.VerifySsconf(ssconf)
            except Exception as e:
                self.fail(f"Unexpected exception raised: {e}")
        else:
            with self.assertRaises(expected_error):
                node_daemon_setup.VerifySsconf(ssconf)

    def testNoSsconf(self):
        self._Check({}, _SetupError)

    def testSuccess(self):
        self._Check(self.valid_ssconf)

    def testInvalidKey(self):
        invalid_ssconf = {
            NDS_SSCONF: {
                "invalid_key": "some_value"
            }
        }
        self._Check(invalid_ssconf, _SetupError)

    def testMissingClusterName(self):
        invalid_ssconf = {
            NDS_SSCONF: {
                SS_INSTANCE_LIST: ["instance1", "instance2"]
            }
        }
        self._Check(invalid_ssconf, _SetupError)

    def testEmptyClusterName(self):
        invalid_ssconf = {
            NDS_SSCONF: {
                SS_CLUSTER_NAME: "",
                SS_INSTANCE_LIST: ["instance1", "instance2"]
            }
        }
        self._Check(invalid_ssconf, _SetupError)

    def testInvalidClusterNameType(self):
        invalid_ssconf = {
            NDS_SSCONF: {
                SS_CLUSTER_NAME: 123,
                SS_INSTANCE_LIST: ["instance1", "instance2"]
            }
        }
        self._Check(invalid_ssconf, _SetupError)

    def testMissingInstanceList(self):
        invalid_ssconf = {
            NDS_SSCONF: {
                SS_CLUSTER_NAME: "test-cluster"
            }
        }
        self._Check(invalid_ssconf, _SetupError)

    def testInvalidInstanceListType(self):
        invalid_ssconf = {
            NDS_SSCONF: {
                SS_CLUSTER_NAME: "test-cluster",
                SS_INSTANCE_LIST: "not-a-list"
            }
        }
        self._Check(invalid_ssconf, _SetupError)

    def testEmptyInstanceList(self):
        invalid_ssconf = {
            NDS_SSCONF: {
                SS_CLUSTER_NAME: "test-cluster",
                SS_INSTANCE_LIST: []
            }
        }
        self._Check(invalid_ssconf)

    def testSpecialCharactersInClusterName(self):
        valid_ssconf = {
            NDS_SSCONF: {
                SS_CLUSTER_NAME: "cluster-with-special_chars123",
                SS_INSTANCE_LIST: ["instance1"]
            }
        }
        self._Check(valid_ssconf)

    def testLongClusterName(self):
        long_cluster_name = "a" * 255
        valid_ssconf = {
            NDS_SSCONF: {
                SS_CLUSTER_NAME: long_cluster_name,
                SS_INSTANCE_LIST: ["instance1"]
            }
        }
        self._Check(valid_ssconf)

def setUpModule():
    testutils.setup_logging()

if __name__ == "__main__":
    unittest.main()

import vk
import json
import logging
import time
import random
from typing import List, Dict, Set
from sentiment_classifiers import SentimentClassifier

class VkFeatureProvider:
    def __init__(self, app_id: str, access_token: str):
        self._vk_api = vk.API(access_token=access_token, app_id=app_id)
        self._clf = SentimentClassifier()
        self._rate_limit = 3  # requests per second
        self._logger = logging.getLogger('VkFeatureProvider')

    def get_news(self, source_id: int, count: int = 100) -> List[Dict]:
        try:
            time.sleep(1 / self._rate_limit)
            wall_posts = self._vk_api.wall.get(owner_id=source_id, count=count)

            processed_posts = []
            for post in wall_posts['items']:
                sentiment = self._clf.classify(post['text'])
                processed_post = {
                    'id': post['id'],
                    'text': post['text'],
                    'sentiment': sentiment,
                    'likes': post.get('likes', {}).get('count', 0)
                }
                processed_posts.append(processed_post)

            return processed_posts

        except Exception as e:
            self._logger.error(f"News retrieval error: {e}")
            return []

    def friends_intersect(self, user_ids: List[int]) -> Set[int]:
        try:
            friend_sets = []
            for uid in user_ids:
                time.sleep(1 / self._rate_limit)
                friends = set(self._vk_api.friends.get(user_id=uid))
                friend_sets.append(friends)

            return set.intersection(*friend_sets)

        except Exception as e:
            self._logger.error(f"Friends intersection error: {e}")
            return set()

    def get_user_info(self, user_id: int) -> Dict:
        try:
            time.sleep(1 / self._rate_limit)
            user_data = self._vk_api.users.get(
                user_ids=user_id, 
                fields=['bdate', 'city', 'education', 'sex']
            )[0]

            return {
                'id': user_data.get('id'),
                'first_name': user_data.get('first_name'),
                'last_name': user_data.get('last_name'),
                'city': user_data.get('city', {}).get('title'),
                'birthdate': user_data.get('bdate'),
                'sex': 'male' if user_data.get('sex') == 1 else 'female'
            }

        except Exception as e:
            self._logger.error(f"User info retrieval error: {e}")
            return {}

    def get_uid_set_info(self, user_ids: List[int]) -> List[Dict]:
        user_info_list = []
        for uid in user_ids:
            user_info = self.get_user_info(uid)
            if user_info:
                user_info_list.append(user_info)

        return user_info_list

    def export_data(self, data: List[Dict], filename: str):
        try:
            with open(filename, 'w', encoding='utf-8') as f:
                json.dump(data, f, ensure_ascii=False, indent=4)
            self._logger.info(f"Data exported to {filename}")

        except Exception as e:
            self._logger.error(f"Export error: {e}")

def main():
    logging.basicConfig(level=logging.INFO)

    # Example usage
    vk_provider = VkFeatureProvider(
        app_id='your_app_id', 
        access_token='your_access_token'
    )

    # Retrieve news
    news_data = vk_provider.get_news(source_id=-29534144, count=50)

    # Find intersecting friends
    intersected_friends = vk_provider.friends_intersect([123456, 789012])

    # Get user info
    user_info = vk_provider.get_user_info(123456)

    # Export data
    vk_provider.export_data(news_data, 'news_data.json')

if __name__ == "__main__":
    main()

import pygame
import sys
import os

pygame.init()
screen_width, screen_height = 800, 600
screen = pygame.display.set_mode((screen_width, screen_height))
pygame.display.set_caption("Interactive Level Editor")

BLACK = (0, 0, 0)
WHITE = (255, 255, 255)
RED = (255, 0, 0)
GREEN = (0, 255, 0)
BLUE = (0, 0, 255)

class GameObject(pygame.sprite.Sprite):
    def __init__(self, x, y, width, height, color):
        super().__init__()
        self.image = pygame.Surface([width, height])
        self.image.fill(color)
        self.rect = self.image.get_rect()
        self.rect.x = x
        self.rect.y = y
        self.velocity_x = 0
        self.velocity_y = 0
        self.gravity = 0.5
        self.on_ground = False

    def update(self):
        self.velocity_y += self.gravity
        self.rect.x += self.velocity_x
        self.rect.y += self.velocity_y

class DrawnObject(pygame.sprite.Sprite):
    def __init__(self, points, color=BLACK, width=3):
        super().__init__()
        self.points = points
        self.color = color
        self.width = width
        self.surface = pygame.Surface((screen_width, screen_height), pygame.SRCALPHA)
        pygame.draw.lines(self.surface, self.color, False, self.points, self.width)
        self.rect = self.surface.get_rect()

    def draw(self, surface):
        surface.blit(self.surface, (0, 0))

class Level0:
    def __init__(self):
        self.activeSprites = pygame.sprite.Group()
        self.drawnSprites = pygame.sprite.Group()

        self.npc = GameObject(100, 100, 30, 50, RED)
        self.block1 = GameObject(0, screen_height - 50, screen_width, 50, GREEN)

        self.activeSprites.add(self.npc)
        self.activeSprites.add(self.block1)

        self.is_drawing = False
        self.current_points = []
        self.max_points = 100

    def handle_events(self):
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                pygame.quit()
                sys.exit()

            self.processKeyDown(event)
            self.processMouseMotion(event)
            self.processMouseButtonDown(event)
            self.processMouseButtonUp(event)

    def processKeyDown(self, event):
        if event.type == pygame.KEYDOWN:
            if event.key == pygame.K_LEFT:
                self.npc.velocity_x = -5
            elif event.key == pygame.K_RIGHT:
                self.npc.velocity_x = 5
            elif event.key == pygame.K_SPACE and self.npc.on_ground:
                self.npc.velocity_y = -10

        if event.type == pygame.KEYUP:
            if event.key in [pygame.K_LEFT, pygame.K_RIGHT]:
                self.npc.velocity_x = 0

    def processMouseMotion(self, event):
        if event.type == pygame.MOUSEMOTION and self.is_drawing:
            if len(self.current_points) < self.max_points:
                self.current_points.append(event.pos)

    def processMouseButtonDown(self, event):
        if event.type == pygame.MOUSEBUTTONDOWN and event.button == 1:
            self.is_drawing = True
            self.current_points = [event.pos]

    def processMouseButtonUp(self, event):
        if event.type == pygame.MOUSEBUTTONUP and event.button == 1:
            self.is_drawing = False
            if len(self.current_points) > 1:
                drawn_path = DrawnObject(self.current_points)
                self.drawnSprites.add(drawn_path)

    def checkCollisions(self):
        collision_list = pygame.sprite.spritecollide(self.npc, self.activeSprites, False)
        self.npc.on_ground = False

        for sprite in collision_list:
            if sprite != self.npc:
                if self.npc.velocity_y > 0 and self.npc.rect.bottom > sprite.rect.top:
                    self.npc.rect.bottom = sprite.rect.top
                    self.npc.velocity_y = 0
                    self.npc.on_ground = True

    def update(self):
        self.activeSprites.update()
        self.checkCollisions()

    def render(self):
        screen.fill(WHITE)
        self.activeSprites.draw(screen)

        for sprite in self.drawnSprites:
            sprite.draw(screen)

        pygame.display.flip()

    def run(self):
        clock = pygame.time.Clock()
        while True:
            self.handle_events()
            self.update()
            self.render()
            clock.tick(60)

if __name__ == "__main__":
    game = Level0()
    game.run()

import os
import re
from typing import List, Optional, Dict, Any

class NamespaceResolver:
    def __init__(self, search_paths: List[str], extensions: List[str] = None):
        self.search_paths = search_paths or ['.']
        self.extensions = extensions or ['.json', '.idl']
        self._namespace_cache: Dict[str, Any] = {}

    def _normalize_namespace(self, namespace: str) -> str:
        """Normalize namespace to standard format."""
        return namespace.replace('::', '.').strip('.')

    def _generate_filenames(self, namespace: str) -> List[str]:
        """Generate potential filenames for a given namespace."""
        parts = namespace.split('.')
        candidates = []

        # Generate various filename variations
        for i in range(len(parts), 0, -1):
            current_parts = parts[:i]
            base_name = '_'.join(current_parts).lower()

            # Add variations for different naming conventions
            candidates.extend([
                base_name,
                ''.join(p.capitalize() for p in current_parts),
                base_name + '_schema',
                base_name + '_types'
            ])

        return candidates

    def _search_schema_files(self, namespace: str) -> Optional[str]:
        """Search for schema files across multiple directories."""
        filenames = self._generate_filenames(namespace)

        for search_path in self.search_paths:
            for filename in filenames:
                for ext in self.extensions:
                    full_path = os.path.join(search_path, filename + ext)
                    if os.path.exists(full_path):
                        return full_path
        return None

    def resolve_namespace(self, namespace: str) -> Optional[Dict[str, Any]]:
        """Resolve a namespace and load its schema."""
        normalized_ns = self._normalize_namespace(namespace)

        # Check cache first
        if normalized_ns in self._namespace_cache:
            return self._namespace_cache[normalized_ns]

        # Search for schema file
        schema_file = self._search_schema_files(normalized_ns)
        if schema_file:
            try:
                schema_data = self._load_schema(schema_file)
                self._namespace_cache[normalized_ns] = schema_data
                return schema_data
            except Exception as e:
                print(f"Error loading schema for {namespace}: {e}")

        return None

    def resolve_type(self, type_name: str, context_namespace: str = None) -> Optional[Dict[str, Any]]:
        """Resolve a specific type within a namespace context."""
        # Split type name and namespace
        parts = type_name.split('.')
        if len(parts) > 1:
            namespace = '.'.join(parts[:-1])
            type_name = parts[-1]
        elif context_namespace:
            namespace = context_namespace

        # Resolve namespace and find type
        namespace_schema = self.resolve_namespace(namespace)
        if namespace_schema:
            return namespace_schema.get('types', {}).get(type_name)

        return None

    def _load_schema(self, schema_path: str) -> Dict[str, Any]:
        """Load and parse schema file."""
        # Placeholder for actual schema loading logic
        with open(schema_path, 'r') as f:
            return {
                'namespace': os.path.splitext(os.path.basename(schema_path))[0],
                'types': {}
            }

    def register_search_path(self, path: str):
        """Add additional search path for schemas."""
        if path not in self.search_paths:
            self.search_paths.append(path)

    def clear_cache(self):
        """Clear namespace resolution cache."""
        self._namespace_cache.clear()

from twisted.internet import defer
from twisted.internet.defer import inlineCallbacks, returnValue
from pixelated.adapter.search import SearchEngine
from pixelated.adapter.mail_store import SearchableMailStore
from pixelated.adapter.services import MailService, DraftService, FeedbackService

class EmailServicesInitializer:
    def __init__(self, session, encryption_key):
        self._session = session
        self._encryption_key = encryption_key
        self._search_engine = None
        self._mail_store = None
        self._mail_service = None
        self._draft_service = None
        self._feedback_service = None

    @inlineCallbacks
    def setup(self):
        try:
            yield self._configure_search_engine()
            yield self._setup_searchable_mail_store()
            yield self._initialize_mail_services()
            yield self._index_existing_mails()
            returnValue(True)
        except Exception as e:
            print(f"Email services initialization failed: {e}")
            returnValue(False)

    @inlineCallbacks
    def _configure_search_engine(self):
        search_storage_key = self._generate_search_key()
        self._search_engine = SearchEngine(
            index_path=self._session.search_index_path,
            encryption_key=search_storage_key
        )
        yield self._search_engine.initialize()
        returnValue(self._search_engine)

    def _generate_search_key(self):
        return f"search_key_{self._session.user_id}_{self._encryption_key}"

    @inlineCallbacks
    def _setup_searchable_mail_store(self):
        self._mail_store = SearchableMailStore(
            search_engine=self._search_engine,
            mail_store_path=self._session.mail_store_path
        )
        yield self._mail_store.initialize()
        returnValue(self._mail_store)

    @inlineCallbacks
    def _initialize_mail_services(self):
        self._mail_service = MailService(
            mail_store=self._mail_store,
            search_engine=self._search_engine
        )

        self._draft_service = DraftService(
            mail_store=self._mail_store
        )

        self._feedback_service = FeedbackService(
            session=self._session
        )

        yield self._mail_service.start()
        yield self._draft_service.start()
        yield self._feedback_service.start()

        returnValue({
            'mail_service': self._mail_service,
            'draft_service': self._draft_service,
            'feedback_service': self._feedback_service
        })

    @inlineCallbacks
    def _index_existing_mails(self):
        existing_mails = yield self._mail_store.get_all_mails()
        for mail in existing_mails:
            yield self._search_engine.index_mail(mail)
        returnValue(len(existing_mails))

    def get_services(self):
        return {
            'search_engine': self._search_engine,
            'mail_store': self._mail_store,
            'mail_service': self._mail_service,
            'draft_service': self._draft_service,
            'feedback_service': self._feedback_service
        }

import unittest
import re

def siteswap_char_to_int(char):
    """Convert siteswap character to integer representation."""
    if char.isdigit():
        return int(char)
    elif 'a' <= char.lower() <= 'z':
        return ord(char.lower()) - ord('a') + 10
    else:
        raise ValueError(f"Invalid siteswap character: {char}")

def siteswap_int_to_char(value):
    """Convert integer to siteswap character representation."""
    if 0 <= value <= 9:
        return str(value)
    elif 10 <= value <= 35:
        return chr(value - 10 + ord('a'))
    else:
        raise ValueError(f"Invalid siteswap integer: {value}")

def is_valid_siteswap_syntax(pattern, mode='solo'):
    """
    Validate siteswap pattern syntax.

    Args:
        pattern (str): Siteswap notation pattern
        mode (str): 'solo' or 'passing'

    Returns:
        bool: Syntax validation result
    """
    if mode == 'solo':
        pattern_regex = r'^[0-9a-z]+$'
    elif mode == 'passing':
        pattern_regex = r'^(\([0-9a-z]+\))+$'
    else:
        raise ValueError("Invalid mode. Must be 'solo' or 'passing'.")

    return bool(re.match(pattern_regex, pattern, re.IGNORECASE))

class SiteswapUtilsTests(unittest.TestCase):
    def test_char_to_int_conversion(self):
        test_cases = [
            ('0', 0), ('5', 5), ('9', 9),
            ('a', 10), ('b', 11), ('z', 35)
        ]

        for char, expected in test_cases:
            self.assertEqual(siteswap_char_to_int(char), expected)

    def test_int_to_char_conversion(self):
        test_cases = [
            (0, '0'), (5, '5'), (9, '9'),
            (10, 'a'), (11, 'b'), (35, 'z')
        ]

        for value, expected in test_cases:
            self.assertEqual(siteswap_int_to_char(value), expected)

    def test_conversion_exceptions(self):
        invalid_chars = ['!', '@', '~']
        invalid_ints = [-1, 36, 100]

        for char in invalid_chars:
            with self.assertRaises(ValueError):
                siteswap_char_to_int(char)

        for value in invalid_ints:
            with self.assertRaises(ValueError):
                siteswap_int_to_char(value)

class SiteSwapSyntaxValidationTests(unittest.TestCase):
    def test_solo_pattern_validation(self):
        solo_patterns = [
            '534', '633', 'a5a', '9988',
            'b451', '42', '7'
        ]
        invalid_solo_patterns = [
            '53.4', 'abc123', '', '!@#'
        ]

        for pattern in solo_patterns:
            self.assertTrue(is_valid_siteswap_syntax(pattern))

        for pattern in invalid_solo_patterns:
            self.assertFalse(is_valid_siteswap_syntax(pattern))

    def test_passing_pattern_validation(self):
        passing_patterns = [
            '(53)', '(b42)', '(a5)(b3)',
            '(9988)(7654)'
        ]
        invalid_passing_patterns = [
            '53', '(a)(b', '!@#', '(53)42'
        ]

        for pattern in passing_patterns:
            self.assertTrue(is_valid_siteswap_syntax(pattern, mode='passing'))

        for pattern in invalid_passing_patterns:
            self.assertFalse(is_valid_siteswap_syntax(pattern, mode='passing'))

