    unittest.main()

#!/usr/bin/env python3

"""Sample High-Energy Filter Utility

Usage:
    sample_filter.py [options] <directory>

Options:
    -t, --threshold FLOAT    Energy threshold multiplier [default: 1.5]
    -r, --reference PATH     Reference energy file path
    -o, --output PATH        Output file for high-energy samples
    -v, --verbose            Enable verbose logging
    -h, --help               Display this help message
"""

import os
import sys
import logging
from typing import List, Dict, Tuple
from docopt import docopt
from datetime import datetime
from nappy.napsys import NAPSystem

class SampleFilter:
    def __init__(self, 
                 root_directory: str, 
                 energy_threshold: float = 1.5, 
                 verbose: bool = False):
        self.root_directory = root_directory
        self.energy_threshold = energy_threshold
        self.verbose_mode = verbose
        self.logger = self._configure_logging()
        self.sample_groups = {}
        self.high_energy_samples = []

    def _configure_logging(self) -> logging.Logger:
        logging.basicConfig(
            level=logging.INFO if self.verbose_mode else logging.WARNING,
            format='%(asctime)s - %(levelname)s: %(message)s'
        )
        return logging.getLogger(__name__)

    def discover_samples(self) -> None:
        """Scan directory and group samples by prefix"""
        for root, _, files in os.walk(self.root_directory):
            for file in files:
                if file.endswith('.xyz'):
                    sample_path = os.path.join(root, file)
                    group_prefix = self._extract_group_prefix(file)

                    if group_prefix not in self.sample_groups:
                        self.sample_groups[group_prefix] = []

                    self.sample_groups[group_prefix].append(sample_path)

    def _extract_group_prefix(self, filename: str) -> str:
        """Extract group prefix from filename"""
        return filename.split('_')[0]

    def compute_energy_per_atom(self, sample_path: str) -> float:
        """Calculate normalized energy per atom"""
        try:
            system = NAPSystem(sample_path)
            total_energy = system.get_total_energy()
            num_atoms = len(system.atoms)
            return total_energy / num_atoms if num_atoms > 0 else float('inf')
        except Exception as e:
            self.logger.error(f"Energy calculation error: {e}")
            return float('inf')

    def identify_high_energy_samples(self) -> None:
        """Identify high-energy samples within each group"""
        for group, samples in self.sample_groups.items():
            if len(samples) < 2:
                continue

            energy_map = {path: self.compute_energy_per_atom(path) for path in samples}
            min_energy = min(energy_map.values())

            high_energy_threshold = min_energy * self.energy_threshold

            self.high_energy_samples.extend([
                path for path, energy in energy_map.items() 
                if energy > high_energy_threshold
            ])

    def generate_report(self, output_path: str = None) -> None:
        """Generate report of high-energy samples"""
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        default_output = f"high_energy_samples_{timestamp}.txt"
        output_file = output_path or default_output

        with open(output_file, 'w') as f:
            for sample in self.high_energy_samples:
                f.write(f"{sample}\n")

        self.logger.info(f"High-energy samples report: {output_file}")

def main():
    arguments = docopt(__doc__)

    try:
        filter_instance = SampleFilter(
            root_directory=arguments['<directory>'],
            energy_threshold=float(arguments['--threshold']),
            verbose=arguments['--verbose']
        )

        filter_instance.discover_samples()
        filter_instance.identify_high_energy_samples()
        filter_instance.generate_report(arguments['--output'])

    except Exception as e:
        logging.error(f"Execution failed: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()

