class TestParsableMixin:
    def test_parsing_with_valid_config(self, sample_file):
        parsing_config = {
            'name': r'Name:\s*(.+)',
            'version': r'Version:\s*(.+)',
            'active': r'Active:\s*(.+)'
        }
        parsable_file = ParsableFile(sample_file, parsing_config)
        result = parsable_file.read()

        assert result.name == 'John Doe'
        assert result.version == '1.2.3'
        assert result.active == 'True'

    def test_parsing_with_partial_config(self, sample_file):
        parsing_config = {
            'name': r'Name:\s*(.+)',
            'version': r'Version:\s*(.+)'
        }
        parsable_file = ParsableFile(sample_file, parsing_config)
        result = parsable_file.read()

        assert result.name == 'John Doe'
        assert result.version == '1.2.3'
        assert result.active is None

    def test_parsing_with_empty_file(self, empty_file):
        parsing_config = {
            'name': r'Name:\s*(.+)',
            'version': r'Version:\s*(.+)'
        }
        parsable_file = ParsableFile(empty_file, parsing_config)
        result = parsable_file.read()

        assert result.name is None
        assert result.version is None

    def test_parsing_with_no_matches(self, sample_file):
        parsing_config = {
            'unknown': r'Unknown:\s*(.+)'
        }
        parsable_file = ParsableFile(sample_file, parsing_config)
        result = parsable_file.read()

        assert result.unknown is None

    def test_file_read_error(self):
        with pytest.raises(RuntimeError):
            parsing_config = {
                'name': r'Name:\s*(.+)'
            }
            parsable_file = ParsableFile('/non/existent/file', parsing_config)
            parsable_file.read()

