from rest_framework.fields import empty

class SplitField(serializers.Field):
    def __init__(self, fields=None, *args, **kwargs):
        self.split_fields = fields or []
        super(SplitField, self).__init__(*args, **kwargs)

    def to_representation(self, value):
        return {field: getattr(value, field, None) for field in self.split_fields}

    def to_internal_value(self, data):
        return data

class SlugChoiceField(serializers.ChoiceField):
    def to_representation(self, value):
        return value.slug if value else None

    def to_internal_value(self, data):
        try:
            return next(choice for choice in self.choices if choice.slug == data)
        except StopIteration:
            raise serializers.ValidationError(_("Invalid choice selected."))

class SlugModelChoiceField(serializers.SlugRelatedField):
    def get_queryset(self):
        return self.queryset

class FeedAppSerializer(serializers.ModelSerializer):
    name = TranslationSerializerField(required=True)
    description = TranslationSerializerField(required=False, allow_null=True)
    categories = SlugModelChoiceField(
        slug_field='slug',
        many=True,
        queryset=None,
        required=False
    )
    carriers = SlugChoiceField(
        choices=MarketCarrier.objects.all(),
        required=False,
        allow_null=True
    )
    regions = SlugChoiceField(
        choices=MarketRegion.objects.all(),
        required=False,
        allow_null=True
    )

    class Meta:
        model = FeedApp
        fields = ('id', 'name', 'description', 'categories', 'carriers', 'regions')

class FeedItemSerializer(serializers.ModelSerializer):
    ITEM_TYPE_CHOICES = (
        ('app', 'App'),
        ('collection', 'Collection'),
        ('brand', 'Brand')
    )

    app = serializers.PrimaryKeyRelatedField(
        queryset=FeedApp.objects.all(),
        required=False,
        allow_null=True
    )
    collection = serializers.PrimaryKeyRelatedField(
        queryset=None,
        required=False,
        allow_null=True
    )
    brand = serializers.PrimaryKeyRelatedField(
        queryset=None,
        required=False,
        allow_null=True
    )

    item_type = serializers.ChoiceField(choices=ITEM_TYPE_CHOICES)
    extra_fields = SplitField(fields=['background_color', 'logo_url'])

    class Meta:
        model = FeedItem
        fields = ('id', 'app', 'collection', 'brand', 'item_type', 'extra_fields')

    def validate(self, data):
        item_type = data.get('item_type')
        item_count = sum(1 for key in ['app', 'collection', 'brand'] if data.get(key) is not None)

        if item_count > 1:
            raise ValidationError(_("Only one item type can be specified."))

        if item_count == 0:
            raise ValidationError(_("An item must be specified."))

        if item_type == 'app' and not data.get('app'):
            raise ValidationError(_("App item type requires an app."))
        elif item_type == 'collection' and not data.get('collection'):
            raise ValidationError(_("Collection item type requires a collection."))
        elif item_type == 'brand' and not data.get('brand'):
            raise ValidationError(_("Brand item type requires a brand."))

        return data

    def get_item_type(self, obj):
        if obj.app:
            return 'app'
        elif obj.collection:
            return 'collection'
        elif obj.brand:
            return 'brand'
        return None

