from odoo import api, fields, models
from odoo.http import request

class EventEvent(models.Model):
    _inherit = 'event.event'

    community_menu = fields.Boolean(
        string='Community Menu',
        help='Enable community-specific menu for this event',
        default=False
    )
    community_menu_ids = fields.One2many(
        'website.menu', 
        'event_id', 
        string='Community Menu Entries',
        domain=[('menu_type', '=', 'community')]
    )

    @api.depends('website_published', 'community_menu')
    def _compute_community_menu(self):
        """Compute visibility and generation of community menus"""
        for event in self:
            if event.website_published and event.community_menu:
                event._update_website_menus()
            else:
                event.community_menu_ids.unlink()

    def _update_website_menus(self):
        """Generate and update website menus for event"""
        websites = self.env['website'].search([])
        for website in websites:
            menu_entries = self._get_community_menu_entries(website)
            track_entries = self._get_track_menu_entries(website)
            proposal_entries = self._get_track_proposal_menu_entries(website)

            existing_menus = self.env['website.menu'].search([
                ('event_id', '=', self.id),
                ('website_id', '=', website.id)
            ])
            existing_menus.unlink()

            for entry in menu_entries + track_entries + proposal_entries:
                self.env['website.menu'].create({
                    'name': entry.get('name'),
                    'url': entry.get('url'),
                    'parent_id': entry.get('parent_id', False),
                    'sequence': entry.get('sequence', 50),
                    'website_id': website.id,
                    'event_id': self.id,
                    'menu_type': entry.get('menu_type', 'community')
                })

    def _get_community_menu_entries(self, website):
        """Generate community-specific menu entries"""
        return [{
            'name': 'Community',
            'url': f'/event/{self.id}/community',
            'sequence': 10,
            'menu_type': 'community'
        }]

    def _get_track_menu_entries(self, website):
        """Generate event track menu entries"""
        return [{
            'name': 'Tracks',
            'url': f'/event/{self.id}/tracks',
            'sequence': 20,
            'menu_type': 'track'
        }]

    def _get_track_proposal_menu_entries(self, website):
        """Generate track proposal menu entries"""
        return [{
            'name': 'Propose a Track',
            'url': f'/event/{self.id}/tracks/propose',
            'sequence': 30,
            'menu_type': 'track_proposal'
        }]

    @api.model
    def create(self, vals):
        """Override create to handle menu generation"""
        event = super().create(vals)
        if event.website_published and event.community_menu:
            event._update_website_menus()
        return event

    def write(self, vals):
        """Override write to handle menu updates"""
        result = super().write(vals)
        if 'website_published' in vals or 'community_menu' in vals:
            for event in self:
                if event.website_published and event.community_menu:
                    event._update_website_menus()
                else:
                    event.community_menu_ids.unlink()
        return result

import sys
import time
import json
import logging
import random
from tornado.ioloop import IOLoop
from tornado.httpclient import AsyncHTTPClient, HTTPRequest
from tornado.web import Application, RequestHandler
from tornado.gen import coroutine, Return

class TorrentTestClient:
    def __init__(self, username, password, debug=False):
        self.username = username
        self.password = password
        self.debug_mode = debug
        self.session_token = None
        self.client = AsyncHTTPClient()
        self.logger = self._configure_logging()

    def _configure_logging(self):
        logger = logging.getLogger('TorrentTestClient')
        logger.setLevel(logging.DEBUG if self.debug_mode else logging.INFO)
        handler = logging.StreamHandler(sys.stdout)
        formatter = logging.Formatter('%(asctime)s - %(levelname)s: %(message)s')
        handler.setFormatter(formatter)
        logger.addHandler(handler)
        return logger

    @coroutine
    def test_login(self):
        try:
            login_request = HTTPRequest(
                url='https://torrent-client.example.com/login',
                method='POST',
                body=json.dumps({
                    'username': self.username,
                    'password': self.password
                })
            )
            response = yield self.client.fetch(login_request)

            if response.code == 200:
                self.session_token = response.headers.get('X-Session-Token')
                self.logger.info(f"Login successful for {self.username}")
                raise Return(True)
            else:
                self.logger.error("Login failed")
                raise Return(False)
        except Exception as e:
            self.logger.error(f"Login error: {e}")
            raise Return(False)

    @coroutine
    def generate_torrent_hash(self):
        hash_value = ''.join(random.choices('0123456789abcdef', k=40))
        self.logger.debug(f"Generated torrent hash: {hash_value}")
        raise Return(hash_value)

    @coroutine
    def fetch_files(self, torrent_hash):
        try:
            files_request = HTTPRequest(
                url=f'https://torrent-client.example.com/torrents/{torrent_hash}/files',
                headers={'X-Session-Token': self.session_token}
            )
            response = yield self.client.fetch(files_request)
            files = json.loads(response.body)
            self.logger.info(f"Retrieved {len(files)} files for torrent {torrent_hash}")
            raise Return(files)
        except Exception as e:
            self.logger.error(f"File retrieval error: {e}")
            raise Return([])

    @coroutine
    def fetch_metadata(self, torrent_hash):
        try:
            metadata_request = HTTPRequest(
                url=f'https://torrent-client.example.com/torrents/{torrent_hash}/metadata',
                headers={'X-Session-Token': self.session_token}
            )
            response = yield self.client.fetch(metadata_request)
            metadata = json.loads(response.body)
            self.logger.debug(f"Metadata retrieved for {torrent_hash}")
            raise Return(metadata)
        except Exception as e:
            self.logger.error(f"Metadata retrieval error: {e}")
            raise Return(None)

    @coroutine
    def webseed_links(self, torrent_hash, num_links=5):
        try:
            webseed_request = HTTPRequest(
                url=f'https://torrent-client.example.com/torrents/{torrent_hash}/webseeds',
                headers={'X-Session-Token': self.session_token}
            )
            response = yield self.client.fetch(webseed_request)
            links = json.loads(response.body)[:num_links]
            self.logger.info(f"Retrieved {len(links)} webseed links")
            raise Return(links)
        except Exception as e:
            self.logger.error(f"Webseed link retrieval error: {e}")
            raise Return([])

    @coroutine
    def run_test_sequence(self):
        login_result = yield self.test_login()
        if not login_result:
            self.logger.error("Aborting test sequence due to login failure")
            raise Return(False)

        torrent_hash = yield self.generate_torrent_hash()
        files = yield self.fetch_files(torrent_hash)
        metadata = yield self.fetch_metadata(torrent_hash)
        webseed_links = yield self.webseed_links(torrent_hash)

        return {
            'torrent_hash': torrent_hash,
