import numpy as np

class Combiner:
    def __init__(self, input_dim, output_dim):
        self.weights = np.random.randn(output_dim, input_dim) * 0.01
        self.bias = np.zeros((output_dim, 1))
        self.input_array = None
        self.output_array = None

    def forward(self, input_array):
        self.input_array = input_array
        self.output_array = np.dot(self.weights, input_array) + self.bias
        return self.output_array

    def gradient(self, output_gradient):
        weights_gradient = np.dot(output_gradient, self.input_array.T)
        input_gradient = np.dot(self.weights.T, output_gradient)
        return input_gradient, weights_gradient

    def update(self, weights_gradient, learning_rate):
        self.weights -= learning_rate * weights_gradient

class Linear(Combiner):
    def __init__(self, input_dim, output_dim):
        super().__init__(input_dim, output_dim)

    def activation(self, x):
        return 1 / (1 + np.exp(-x))

    def activation_derivative(self, x):
        return x * (1 - x)

    def forward(self, input_array):
        transformed = super().forward(input_array)
        return self.activation(transformed)

    def backprop(self, output_gradient):
        transformed_derivative = self.activation_derivative(self.output_array)
        modified_gradient = output_gradient * transformed_derivative
        input_gradient, weights_gradient = self.gradient(modified_gradient)
        return input_gradient, weights_gradient

    def learning_rate(self, gradient):
        return np.sqrt(np.sum(gradient ** 2)) * 0.01

    def hessian_approximation(self, gradient):
        return np.diag(gradient ** 2)

    def step_size(self, gradient):
        hessian = self.hessian_approximation(gradient)
        return np.linalg.inv(hessian + np.eye(hessian.shape[0]) * 1e-8)

    def update_backprop(self, weights_gradient):
        learning_rate = self.learning_rate(weights_gradient)
        step = self.step_size(weights_gradient)
        updated_gradient = np.dot(step, weights_gradient)
        self.update(updated_gradient, learning_rate)

class NeuralNetwork:
    def __init__(self, layer_dimensions):
        self.layers = []
        for i in range(len(layer_dimensions) - 1):
            layer = Linear(layer_dimensions[i], layer_dimensions[i+1])
            self.layers.append(layer)

    def forward_pass(self, input_array):
        current = input_array
        for layer in self.layers:
            current = layer.forward(current)
        return current

    def train(self, input_data, target_data, epochs=1000):
        for _ in range(epochs):
            output = self.forward_pass(input_data)
            error_gradient = output - target_data

            for layer in reversed(self.layers):
                error_gradient, weights_gradient = layer.backprop(error_gradient)
                layer.update_backprop(weights_gradient)

    def predict(self, input_data):
        return self.forward_pass(input_data)

