from ipaclient.frontend import Registry
from ipalib import errors, util, x509
from ipalib.cli import command_validate_file_path
from ipalib.parameters import Flag
from ipalib.plugable import Plugin
from ipalib.text import _

register = Registry()

@register(name='user_del')
class user_del(Plugin):
    """
    Delete a user account
    """
    def get_options(self):
        options = super(user_del, self).get_options()
        options.extend([
            Flag('preserve', 
                 doc=_('Preserve user account'),
                 default=False),
            Flag('preserve_home', 
                 doc=_('Preserve user home directory'),
                 default=False)
        ])
        return options

    def forward(self, *args, **kwargs):
        if kwargs.get('preserve', False) and kwargs.get('preserve_home', False):
            raise errors.OptionError(
                _('Cannot specify both preserve and preserve_home options')
            )

        return super(user_del, self).forward(*args, **kwargs)

@register(name='user_show')
class user_show(Plugin):
    """
    Display user account details with certificate support
    """
    def get_options(self):
        options = super(user_show, self).get_options()
        options.extend([
            Flag('certificates', 
                 doc=_('Retrieve user certificates'),
                 default=False),
            Flag('output_file', 
                 doc=_('File path to export certificates'),
                 default=None)
        ])
        return options

    def check_writable_file(self, filename):
        """
        Validate file path for writing certificates
        """
        try:
            command_validate_file_path(filename)
        except ValueError as e:
            raise errors.ValidationError(str(e))

    def write_certificate_list(self, certificates, filename):
        """
        Write certificates to a specified file
        """
        self.check_writable_file(filename)

        try:
            with open(filename, 'wb') as cert_file:
                for cert in certificates:
                    cert_file.write(cert.encode('utf-8') + b'\n')
        except IOError as e:
            raise errors.FileError(str(e))

    def forward(self, *args, **kwargs):
        certificates_flag = kwargs.pop('certificates', False)
        output_file = kwargs.pop('output_file', None)

        result = super(user_show, self).forward(*args, **kwargs)

        if certificates_flag and output_file:
            user_certs = result.get('usercertificate', [])

            if user_certs:
                parsed_certs = []
                for cert_data in user_certs:
                    try:
                        x509_cert = x509.load_der_x509_certificate(cert_data)
                        parsed_certs.append(x509_cert.public_bytes(encoding='PEM').decode('utf-8'))
                    except Exception as e:
                        util.print_error(str(e))

                if parsed_certs:
                    self.write_certificate_list(parsed_certs, output_file)

        return result

import unittest
from algorithms.graphs.complementGraph import generate_complement_graph

class TestComplementGraph(unittest.TestCase):
    def setUp(self):
        # Initialize common graph structures for testing
        self.empty_graph = {}

        self.single_node_graph = {
            'A': {}
        }

        self.fully_connected_graph = {
            'A': {'B': 1, 'C': 1},
            'B': {'A': 1, 'C': 1},
            'C': {'A': 1, 'B': 1}
        }

        self.sparse_graph = {
            'A': {'B': 2},
            'B': {'A': 2, 'C': 3},
            'C': {'B': 3, 'D': 4},
            'D': {'C': 4}
        }

        self.disconnected_graph = {
            'A': {},
            'B': {},
            'C': {},
            'D': {}
        }

    def test_empty_graph_complement(self):
        """Test complement generation for an empty graph"""
        complement = generate_complement_graph(self.empty_graph)
        self.assertEqual(complement, {})

    def test_single_node_graph_complement(self):
        """Test complement generation for a single node graph"""
        complement = generate_complement_graph(self.single_node_graph)
        self.assertEqual(complement, {'A': {}})

    def test_fully_connected_graph_complement(self):
        """Test complement generation for a fully connected graph"""
        complement = generate_complement_graph(self.fully_connected_graph)
        expected_complement = {
            'A': {},
            'B': {},
            'C': {}
        }
        self.assertEqual(complement, expected_complement)

    def test_sparse_graph_complement(self):
        """Test complement generation for a sparse graph"""
        complement = generate_complement_graph(self.sparse_graph)
        expected_complement = {
            'A': {'C': 1, 'D': 1},
            'B': {'D': 1},
            'C': {'A': 1},
            'D': {'A': 1, 'B': 1}
        }
        self.assertEqual(complement, expected_complement)

    def test_disconnected_graph_complement(self):
        """Test complement generation for a disconnected graph"""
        complement = generate_complement_graph(self.disconnected_graph)
        expected_complement = {
            'A': {'B': 1, 'C': 1, 'D': 1},
            'B': {'A': 1, 'C': 1, 'D': 1},
            'C': {'A': 1, 'B': 1, 'D': 1},
            'D': {'A': 1, 'B': 1, 'C': 1}
        }
        self.assertEqual(complement, expected_complement)

    def test_complement_idempotence(self):
        """Test that generating complement twice returns original graph"""
        original_graph = self.sparse_graph.copy()
        first_complement = generate_complement_graph(original_graph)
        second_complement = generate_complement_graph(first_complement)

        self.assertEqual(original_graph, second_complement)

    def test_complement_weight_preservation(self):
        """Test weight preservation in complement graph generation"""
        weighted_graph = {
            'A': {'B': 5, 'C': 3},
            'B': {'A': 5, 'D': 2},
            'C': {'A': 3},
            'D': {'B': 2}
        }
        complement = generate_complement_graph(weighted_graph)

        # Verify default weight is 1 when not specified
        for node in complement:
            for edge_node in complement[node]:
                self.assertEqual(complement[node][edge_node], 1)

if __name__ == '__main__':
    unittest.main()

import socketserver
import socket
import struct
import setproctitle
import chardet
import logging
import threading
import re
import urllib.parse

class RendererHolder:
    def __init__(self):
        self._renderers = {}
        self._lock = threading.Lock()

    def add_renderer(self, uuid, details):
        with self._lock:
            self._renderers[uuid] = details

    def remove_renderer(self, uuid):
        with self._lock:
            if uuid in self._renderers:
                del self._renderers[uuid]

    def get_renderers(self):
        with self._lock:
            return dict(self._renderers)

class SSDPRequestHandler(socketserver.BaseRequestHandler):
    def handle(self):
        data = self.request[0]
        try:
            encoding = chardet.detect(data)['encoding'] or 'utf-8'
            decoded_data = data.decode(encoding, errors='ignore')

            if self._is_notify_method(decoded_data):
                self.server.process_notify(decoded_data)
        except Exception as e:
            logging.error(f"SSDP packet processing error: {e}")

    def _is_notify_method(self, data):
        return "NOTIFY * HTTP/1.1" in data and "NTS: ssdp:alive" in data

class ThreadedSSDPListener(socketserver.ThreadingMixIn, socketserver.UDPServer):
    def __init__(self, server_address, renderer_holder, manual_renderers=None):
        super().__init__(server_address, SSDPRequestHandler)
        self.renderer_holder = renderer_holder
        self.manual_renderers = manual_renderers or []

    def process_notify(self, data):
        try:
            device_details = self._parse_device_details(data)
            if device_details and self._is_valid_renderer(device_details):
                self.renderer_holder.add_renderer(device_details['uuid'], device_details)
        except Exception as e:
            logging.warning(f"Device processing error: {e}")

    def _parse_device_details(self, data):
        headers = {k.lower(): v for k, v in re.findall(r'(.*?): (.*?)\r\n', data)}
        return {
            'uuid': headers.get('usn', ''),
            'location': headers.get('location', ''),
            'server': headers.get('server', '')
        }

    def _is_valid_renderer(self, device):
        return (
            device['location'] and
            ('MediaRenderer' in device.get('server', '') or
             any(manual_url in device['location'] for manual_url in self.manual_renderers))
        )

class RendererDiscover:
    def __init__(self, multicast_group='239.255.255.250', port=1900, manual_renderers=None):
        self.multicast_group = multicast_group
        self.port = port
        self.renderer_holder = RendererHolder()
        self.manual_renderers = manual_renderers or []
        self._listener_thread = None

    def start(self):
        try:
            setproctitle.setproctitle('ssdp_renderer_discovery')
            server = ThreadedSSDPListener(
                ('', self.port),
                self.renderer_holder,
                self.manual_renderers
            )

            sock = server.socket
            sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            sock.bind(('', self.port))

            mreq = struct.pack("4sl", socket.inet_aton(self.multicast_group), socket.INADDR_ANY)
            sock.setsockopt(socket.IPPROTO_IP, socket.IP_ADD_MEMBERSHIP, mreq)

            self._listener_thread = threading.Thread(target=server.serve_forever)
            self._listener_thread.daemon = True
            self._listener_thread.start()
        except Exception as e:
            logging.error(f"SSDP discovery start error: {e}")

    def stop(self):
        if self._listener_thread:
            self._listener_thread.join(timeout=2)

    def get_renderers(self):
        return self.renderer_holder.get_renderers()

def main():
    logging.basicConfig(level=logging.INFO)
    manual_renderers = [
        'http://192.168.1.100:8080/description.xml',
        'http://192.168.1.101:8088/renderer'
    ]

    renderer_discovery = RendererDiscover(manual_renderers=manual_renderers)
    renderer_discovery.start()

if __name__ == "__main__":
    main()

