)

_LOGGER = logging.getLogger(__name__)

ATTR_SETTING = "setting"

async def async_setup_platform(
    hass: HomeAssistant,
    config: Dict[str, Any],
    async_add_entities: callable,
    discovery_info: Optional[Dict[str, Any]] = None
):
    """Set up the IP Webcam settings switches."""
    platform = entity_platform.async_get_current_platform()

    if not discovery_info:
        return

    ipcam = discovery_info.get('ipcam')

    if not ipcam:
        _LOGGER.error("No IP Webcam device found")
        return

    switches = []

    for setting in SUPPORTED_SETTINGS:
        switch = IPWebcamSettingsSwitch(
            ipcam=ipcam,
            setting=setting
        )
        switches.append(switch)

    async_add_entities(switches)

class IPWebcamSettingsSwitch(SwitchEntity):
    """Representation of an IP Webcam settings switch."""

    def __init__(self, ipcam, setting):
        """Initialize the switch."""
        self._ipcam = ipcam
        self._setting = setting
        self._state = False

        self._attr_name = f"IP Webcam {setting.replace('_', ' ').title()}"
        self._attr_unique_id = f"{ipcam.host}_{setting}_switch"

    @property
    def icon(self) -> str:
        """Return the icon for the switch."""
        return ICON_MAPPING.get(self._setting, "mdi:camera")

    @property
    def is_on(self) -> bool:
        """Return true if switch is on."""
        return self._state

    async def async_turn_on(self, **kwargs: Any) -> None:
        """Turn the switch on."""
        try:
            if self._setting == "torch":
                await self._ipcam.async_enable_torch()
            elif self._setting == "video_recording":
                await self._ipcam.async_start_recording()
            else:
                await self._ipcam.async_set_setting(self._setting, "on")

            self._state = True
            self.async_write_ha_state()
        except Exception as e:
            _LOGGER.error(f"Error turning on {self._setting}: {e}")

    async def async_turn_off(self, **kwargs: Any) -> None:
        """Turn the switch off."""
        try:
            if self._setting == "torch":
                await self._ipcam.async_disable_torch()
            elif self._setting == "video_recording":
                await self._ipcam.async_stop_recording()
            else:
                await self._ipcam.async_set_setting(self._setting, "off")

            self._state = False
            self.async_write_ha_state()
        except Exception as e:
            _LOGGER.error(f"Error turning off {self._setting}: {e}")

    async def async_update(self) -> None:
        """Update the state of the switch."""
        try:
            if self._setting == "torch":
                self._state = await self._ipcam.async_is_torch_enabled()
            elif self._setting == "video_recording":
                self._state = await self._ipcam.async_is_recording()
            else:
                current_state = await self._ipcam.async_get_setting(self._setting)
                self._state = current_state.lower() == "on"
        except Exception as e:
            _LOGGER.warning(f"Unable to update {self._setting} state: {e}")
            self._state = False

    async def async_added_to_hass(self) -> None:
        """When entity is added to Home Assistant."""
        await self.async_update()

import hug
import pytest
from collections import namedtuple
from datetime import datetime
from json import loads

class NewObject:
    def __init__(self, value):
        self.value = value

    def __repr__(self):
        return str(self.value)

NamedTupleObject = namedtuple('NamedTupleObject', ['name', 'value'])

now = datetime.now()

test_data = {
    'string': 'hello',
    'integer': 42,
    'float': 3.14,
    'datetime': now,
    'list': [1, 2, 3],
    'nested_dict': {
        'key1': 'value1',
        'key2': 42
    },
    'custom_object': NewObject('test'),
    'named_tuple': NamedTupleObject(name='test', value=100),
    'bytes_data': b'binary_data'
}

def test_text():
    result = hug.output_format.text(test_data)
    assert isinstance(result, str)
    assert 'hello' in result
    assert '42' in result
    assert str(now) in result

def test_json():
    result = hug.output_format.json(test_data)
    assert isinstance(result, str)
    parsed_data = loads(result)
    assert parsed_data['string'] == 'hello'
    assert parsed_data['integer'] == 42
    assert parsed_data['datetime'] == now.isoformat()

def test_pretty_json():
    result = hug.output_format.pretty_json(test_data)
    assert isinstance(result, str)
    assert '\n' in result  # Check for line breaks typical of pretty print
    parsed_data = loads(result)
    assert parsed_data['float'] == 3.14

def test_json_camelcase():
    def to_camel_case(snake_str):
        components = snake_str.split('_')
        return components[0] + ''.join(x.title() for x in components[1:])

    result = hug.output_format.json(test_data, key_transformer=to_camel_case)
    parsed_data = loads(result)
    assert 'nestedDict' in parsed_data
    assert 'customObject' in parsed_data

def test_json_serialization_edge_cases():
    complex_data = {
        'custom': NewObject('complex'),
        'namedtuple': NamedTupleObject(name='complex', value=200)
    }

    with pytest.raises(TypeError):
