def test_datetime_serialization():
    date_data = {'timestamp': now}
    result = hug.output_format.json(date_data)
    parsed_data = loads(result)
    assert parsed_data['timestamp'] == now.isoformat()

def test_bytes_serialization():
    bytes_data = {'binary': b'test_bytes'}
    result = hug.output_format.json(bytes_data)
    parsed_data = loads(result)
    assert parsed_data['binary'] == 'test_bytes'

import os
import sys
import time
import shutil
import subprocess
from distutils.dir_util import copy_tree

class DirectoryManager:
    def __init__(self):
        self.base_paths = {
            'source': os.path.join(os.getcwd(), 'source'),
            'export': os.path.join(os.getcwd(), 'export'),
            'build': os.path.join(os.getcwd(), 'build'),
            'client': os.path.join(os.getcwd(), 'client')
        }
        self.log_file = os.path.join(os.getcwd(), 'directory_setup.log')

    def printLog(self, message):
        timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
        log_entry = f"[{timestamp}] {message}"
        print(log_entry)

        with open(self.log_file, 'a') as log:
            log.write(log_entry + '\n')

    def mkPath(self, path):
        try:
            os.makedirs(path, exist_ok=True)
            self.printLog(f"Created directory: {path}")
        except Exception as e:
            self.printLog(f"Error creating directory {path}: {str(e)}")

    def setup_directories(self):
        # Remove existing log file
        if os.path.exists(self.log_file):
            os.remove(self.log_file)

        # Create base directories
        for category, path in self.base_paths.items():
            self.mkPath(path)

        # Database source directories
        rbank_cmb_source_dirs = [
            os.path.join(self.base_paths['source'], 'rbank_cmb', 'data'),
            os.path.join(self.base_paths['source'], 'rbank_cmb', 'scripts')
        ]
        for dir_path in rbank_cmb_source_dirs:
            self.mkPath(dir_path)

        # Export build directories
        export_build_dirs = [
            os.path.join(self.base_paths['export'], 'rbank_build'),
            os.path.join(self.base_paths['export'], 'render_output')
        ]
        for dir_path in export_build_dirs:
            self.mkPath(dir_path)

        # Client installation directories
        client_install_dirs = [
            os.path.join(self.base_paths['client'], 'resources'),
            os.path.join(self.base_paths['client'], 'plugins')
        ]
        for dir_path in client_install_dirs:
            self.mkPath(dir_path)

        # Lookup directories
        lookup_dirs = [
            os.path.join(self.base_paths['source'], 'ig_lookup'),
            os.path.join(self.base_paths['source'], 'shape_lookup')
        ]
        for dir_path in lookup_dirs:
            self.mkPath(dir_path)

        self.printLog("Directory setup completed successfully.")

    def validate_directories(self):
        for category, path in self.base_paths.items():
            if not os.path.exists(path):
                self.printLog(f"ERROR: {category} directory missing: {path}")
                return False
        return True

def main():
    directory_manager = DirectoryManager()
    directory_manager.setup_directories()

    if directory_manager.validate_directories():
        print("Directory validation successful.")
    else:
        print("Directory validation failed.")

if __name__ == "__main__":
    main()

