class Replacer:
    BIO_FORMATS_ARTIFACT = r'(bio-formats-)(\d+\.\d+\.\d+)(-SNAPSHOT)?'

    def __init__(self, old_version, new_version, old_group=None, new_group=None):
        self.old_version = old_version
        self.new_version = new_version
        self.old_group = old_group
        self.new_group = new_group

    @staticmethod
    def check_version_format(version):
        version_pattern = r'^\d+\.\d+\.\d+(-SNAPSHOT)?$'
        return re.match(version_pattern, version) is not None

    def replace_file(self, filepath):
        try:
            with open(filepath, 'r', encoding='utf-8') as file:
                content = file.read()

            # Replace version references
            modified_content = re.sub(
                r'(<version>)' + re.escape(self.old_version) + r'(</version>)',
                rf'\1{self.new_version}\2',
                content
            )

            # Replace group references if specified
            if self.old_group and self.new_group:
                modified_content = modified_content.replace(
                    self.old_group, self.new_group
                )

            with open(filepath, 'w', encoding='utf-8') as file:
                file.write(modified_content)

            print(f"Updated file: {filepath}")
        except Exception as e:
            print(f"Error processing {filepath}: {e}")

    def bump_pom_versions(self):
        pom_files = glob.glob('./**/pom.xml', recursive=True)
        for pom_file in pom_files:
            self.replace_file(pom_file)

    def bump_java_versions(self):
        java_files = glob.glob('./**/*.java', recursive=True)
        for java_file in java_files:
            with open(java_file, 'r', encoding='utf-8') as file:
                content = file.read()
                if re.search(self.old_version, content):
                    self.replace_file(java_file)

    def bump_stable_version(self):
        if not self.old_version.endswith('-SNAPSHOT'):
            print("Current version is already stable.")
            return

        stable_version = self.old_version.replace('-SNAPSHOT', '')
        if not self.check_version_format(stable_version):
            raise ValueError("Invalid version format")

        self.old_version, self.new_version = stable_version, stable_version
        self.bump_pom_versions()
        self.bump_java_versions()

def main():
    parser = argparse.ArgumentParser(description='Version Management Tool')
    parser.add_argument('old_version', help='Current version')
    parser.add_argument('new_version', help='New version')
    parser.add_argument('--old_group', help='Old group name')
    parser.add_argument('--new_group', help='New group name')
    parser.add_argument('--stable', action='store_true', help='Convert snapshot to stable')

    args = parser.parse_args()

    if not Replacer.check_version_format(args.old_version):
        print("Invalid old version format")
        sys.exit(1)

    if not Replacer.check_version_format(args.new_version):
        print("Invalid new version format")
        sys.exit(1)

    try:
        replacer = Replacer(
            args.old_version, 
            args.new_version, 
            args.old_group, 
            args.new_group
        )

        if args.stable:
            replacer.bump_stable_version()
        else:
            replacer.bump_pom_versions()
            replacer.bump_java_versions()

        print("Version update completed successfully.")

    except Exception as e:
        print(f"Error during version update: {e}")
        sys.exit(1)

if __name__ == '__main__':
    main()

import os
import io
import stat
import time
import threading
import sublime
import sublime_plugin

TAILF_VIEWS = {}
STATUS_KEY = "tail_f_status"

class TailF(threading.Thread):
    def __init__(self, view_id, file_path, interval=1):
        threading.Thread.__init__(self)
        self.view_id = view_id
        self.file_path = file_path
        self.interval = interval
        self.stop_event = threading.Event()
        self.daemon = True

    def run(self):
        last_size = 0
        last_modified = 0

        while not self.stop_event.is_set():
            try:
                file_stats = os.stat(self.file_path)
                current_size = file_stats[stat.ST_SIZE]
                current_modified = file_stats[stat.ST_MTIME]

                if current_size != last_size or current_modified != last_modified:
                    sublime.set_timeout(lambda: self._update_view(), 0)
                    last_size = current_size
                    last_modified = current_modified

                time.sleep(self.interval)

            except Exception as e:
                print(f"TailF Error: {e}")
                break

    def _update_view(self):
        view = sublime.View(self.view_id)
        if view and view.is_valid():
            try:
                with io.open(self.file_path, 'r', encoding='utf-8') as f:
                    content = f.read()

                view.set_read_only(False)
                view.run_command('update_file', {'content': content})
                view.set_read_only(True)
                view.show(view.size())
            except Exception as e:
                print(f"Update View Error: {e}")

    def stop(self):
        self.stop_event.set()

class UpdateFile(sublime_plugin.TextCommand):
    def run(self, edit, content):
        region = sublime.Region(0, self.view.size())
        self.view.replace(edit, region, content)

class StopTailF(sublime_plugin.TextCommand):
    def run(self, edit):
        view_id = self.view.id()
        if view_id in TAILF_VIEWS:
            thread = TAILF_VIEWS[view_id]
            thread.stop()
            del TAILF_VIEWS[view_id]
            self.view.set_status(STATUS_KEY, "")
            self.view.set_read_only(False)

class TailFCommand(sublime_plugin.TextCommand):
    def run(self, edit):
        file_path = self.view.file_name()
        if not file_path:
            sublime.status_message("File must be saved first!")
            return

        view_id = self.view.id()
        if view_id in TAILF_VIEWS:
            sublime.status_message("Already monitoring this file!")
            return

        thread = TailF(view_id, file_path)
        thread.start()
        TAILF_VIEWS[view_id] = thread

        self.view.set_read_only(True)
        self.view.set_status(STATUS_KEY, "Tail -f: Active")

class TailFEventListener(sublime_plugin.EventListener):
    def on_pre_close(self, view):
        view_id = view.id()
        if view_id in TAILF_VIEWS:
            thread = TAILF_VIEWS[view_id]
            thread.stop()
            del TAILF_VIEWS[view_id]

def plugin_loaded():
    for window in sublime.windows():
        for view in window.views():
            view.erase_status(STATUS_KEY)

from collections import defaultdict, deque

class Solution:
    def findLadders(self, beginWord: str, endWord: str, wordList: list[str]) -> list[list[str]]:
        # Handle edge cases
        if endWord not in wordList:
            return []

        # Create word set and add begin word if not present
        word_set = set(wordList)
        word_set.add(beginWord)

        # Precompute letter replacement patterns
        def get_neighbors(word):
            neighbors = []
            for i in range(len(word)):
                for char in 'abcdefghijklmnopqrstuvwxyz':
                    new_word = word[:i] + char + word[i+1:]
                    if new_word in word_set and new_word != word:
                        neighbors.append(new_word)
            return neighbors

        # Bidirectional BFS
        def bfs():
            forward = {beginWord: [[beginWord]]}
            backward = {endWord: [[endWord]]}

            while forward and backward:
                # Choose smaller direction to explore
                if len(forward) > len(backward):
                    forward, backward = backward, forward

                temp = defaultdict(list)
                is_found = False
                word_set_copy = set(word_set)

                # Expand current layer
                for word, paths in forward.items():
                    word_set_copy.discard(word)

                for word, paths in forward.items():
                    for neighbor in get_neighbors(word):
                        if neighbor in backward:
                            is_found = True
                            for back_path in backward[neighbor]:
                                for path in paths:
                                    full_path = path + back_path[::-1][1:]
                                    result.append(full_path)

                        if not is_found and neighbor in word_set_copy:
                            temp[neighbor].extend(
                                [path + [neighbor] for path in paths]
                            )

                if is_found:
                    return

                forward = temp
                word_set.difference_update(temp.keys())

            return

        # Result container
        result = []
        bfs()

        # Return unique transformation paths
        return result if result else []

# Example usage
def main():
    solution = Solution()
    beginWord = "hit"
    endWord = "cog"
    wordList = ["hot","dot","dog","lot","log","cog"]

    ladders = solution.findLadders(beginWord, endWord, wordList)

    print("Word Ladders:")
    for ladder in ladders:
        print(ladder)

if __name__ == "__main__":
    main()

