import urllib

from django import forms
from django.conf import settings
from django.utils.encoding import smart_unicode
from django.utils.translation import ugettext_lazy as _

VERIFY_SERVER = 'www.google.com/recaptcha/api/verify'

default_error_messages = {
    'captcha_invalid': _('Invalid reCAPTCHA. Please try again.'),
    'captcha_error': _('Error verifying reCAPTCHA. Please try again.'),
}

class RecaptchaWidget(forms.Widget):
    def __init__(self, attrs=None):
        self.attrs = attrs or {}
        super(RecaptchaWidget, self).__init__(attrs)

    def render(self, name, value, attrs=None):
        public_key = settings.RECAPTCHA_PUBLIC_KEY

        if not public_key:
            raise ValueError('reCAPTCHA public key not configured')

        html = u'''
            <script type="text/javascript" src="https://www.google.com/recaptcha/api.js"></script>
            <div class="g-recaptcha" data-sitekey="{0}"></div>
        '''.format(public_key)

        return html

    def value_from_datadict(self, data, files, name):
        return data.get('g-recaptcha-response', None)

class RecaptchaField(forms.Field):
    widget = RecaptchaWidget

    def __init__(self, attrs=None, error_messages=None, *args, **kwargs):
        error_messages = error_messages or {}
        default_error_messages.update(error_messages)

        super(RecaptchaField, self).__init__(
            *args, 
            error_messages=default_error_messages, 
            **kwargs
        )

    def clean(self, value):
        super(RecaptchaField, self).clean(value)

        if not value:
            raise forms.ValidationError(
                self.error_messages['captcha_invalid']
            )

        return self.verify(value)

    def verify(self, captcha_response):
        private_key = settings.RECAPTCHA_PRIVATE_KEY

        if not private_key:
            raise ValueError('reCAPTCHA private key not configured')

        params = urllib.urlencode({
            'privatekey': private_key,
            'remoteip': self.get_remote_ip(),
            'challenge': captcha_response,
            'response': captcha_response
        })

        try:
            response = urllib2.urlopen(
                'https://' + VERIFY_SERVER, 
                params
            )
            result = response.read().splitlines()
        except Exception:
            raise forms.ValidationError(
                self.error_messages['captcha_error']
            )

        if result[0].lower() != 'true':
            raise forms.ValidationError(
                self.error_messages['captcha_invalid']
            )

        return captcha_response

    def get_remote_ip(self):
        # Override this method in your form to provide specific IP retrieval
        return ''

