import os
import sys
import json
import simplejson
import urllib.parse
from http.server import HTTPServer, SimpleHTTPRequestHandler

class CSPTestHandler(SimpleHTTPRequestHandler):
    def __init__(self, *args, config=None, **kwargs):
        self.config = config or {}
        super().__init__(*args, **kwargs)

    def _set_headers(self):
        csp_header = (
            f"default-src 'self'; "
            f"media-src {' '.join(self.config.get('media_sources', []))}; "
            f"script-src {' '.join(self.config.get('script_sources', []))}"
        )
        self.send_response(200)
        self.send_header('Content-Type', 'text/html; charset=utf-8')
        self.send_header('Content-Security-Policy', csp_header)
        self.end_headers()

    def do_GET(self):
        if self.path == '/media-csp-test.html':
            self._set_headers()
            self._generate_test_page()
        else:
            super().do_GET()

    def _generate_test_page(self):
        test_page = f"""
        <!DOCTYPE html>
        <html>
        <head>
            <title>Media CSP Test</title>
            <script src="/resources/testharness.js"></script>
            <script src="/resources/testharnessreport.js"></script>
        </head>
        <body>
            <script>
                async_test(function(t) {{
                    var m = document.createElement('audio');
                    m.src = '{self.config.get('audio_url', '')}';
                    m.onloadedmetadata = t.step_func_done(function() {{
                        assert_true(true, 'Audio source loaded successfully');
                    }});
                    m.onerror = t.step_func_done(function() {{
                        assert_unreached('Audio source failed to load');
                    }});
                    document.body.appendChild(m);
                }}, 'Media Source CSP Test');
            </script>
        </body>
        </html>
        """
        self.wfile.write(test_page.encode('utf-8'))

def load_config(config_path):
    try:
        with open(config_path, 'r') as f:
            return simplejson.load(f)
    except (IOError, json.JSONDecodeError) as e:
        print(f"Error loading configuration: {e}")
        sys.exit(1)

def main():
    config_path = os.path.join(os.path.dirname(__file__), 'media_csp_config.json')
    config = load_config(config_path)

    server_address = (config.get('host', 'localhost'), config.get('port', 8000))
    handler = lambda *args, **kwargs: CSPTestHandler(*args, config=config, **kwargs)

    try:
        httpd = HTTPServer(server_address, handler)
        print(f"Serving on http://{server_address[0]}:{server_address[1]}")
        httpd.serve_forever()
    except KeyboardInterrupt:
        print("\nServer stopped.")
    finally:
        httpd.server_close()

if __name__ == '__main__':
    main()

import os
import sys
import shutil
import collections
import subprocess

# Python 2 and 3 compatibility module

# Define compatibility terminal size namedtuple
_terminal_size = collections.namedtuple('TerminalSize', ['columns', 'lines'])

class CompatibilityModule:
    def __init__(self):
        self.python_version = sys.version_info[0]
        self.is_python2 = self.python_version == 2
        self.is_python3 = self.python_version == 3

    def compat_getenv(self, key, default=None, encoding='utf-8'):
        """
        Cross-version compatible environment variable retrieval
        Handles decoding and potential encoding issues
        """
        try:
            value = os.environ.get(key, default)
            if self.is_python2 and isinstance(value, str):
                return value.decode(encoding)
            return value
        except Exception as e:
            return default

    def compat_setenv(self, key, value, overwrite=True, encoding='utf-8'):
        """
        Cross-version compatible environment variable setting
        Manages encoding and potential string/bytes conversions
        """
        try:
            if self.is_python2:
                if isinstance(value, unicode):
                    value = value.encode(encoding)
            os.environ[key] = value
        except Exception:
            pass

    def compat_kwargs(self, kwargs, version_map=None):
        """
        Transform keyword arguments for cross-version compatibility
        """
        version_map = version_map or {}
        if self.is_python2:
            return {version_map.get(k, k): v for k, v in kwargs.items()}
        return kwargs

    def compat_get_terminal_size(self):
        """
        Cross-version terminal size detection with multiple fallback strategies
        """
        try:
            # First attempt: shutil method (Python 3.3+)
            if hasattr(shutil, 'get_terminal_size'):
                size = shutil.get_terminal_size()
                return _terminal_size(size.columns, size.lines)

            # Second attempt: stty method
            try:
                columns = int(subprocess.check_output(['tput', 'cols']).strip())
                lines = int(subprocess.check_output(['tput', 'lines']).strip())
                return _terminal_size(columns, lines)
            except Exception:
                pass

            # Third attempt: environment variables
            columns = int(os.environ.get('COLUMNS', 80))
            lines = int(os.environ.get('LINES', 24))
            return _terminal_size(columns, lines)

        except Exception:
            # Fallback default size
            return _terminal_size(80, 24)

    def compat_input(self, prompt=None):
        """
        Cross-version input function with compatibility layer
        """
        if self.is_python2:
            return raw_input(prompt) if prompt else raw_input()
        return input(prompt) if prompt else input()

    def compat_execfile(self, filepath, globals_dict=None, locals_dict=None):
        """
        Cross-version file execution compatibility
        """
        if self.is_python3:
            with open(filepath, 'r') as f:
                exec(f.read(), globals_dict or {}, locals_dict or {})
        else:
            execfile(filepath, globals_dict, locals_dict)

    def compat_unicode(self, text, encoding='utf-8', errors='strict'):
        """
        Consistent unicode handling across Python versions
        """
        if self.is_python2:
            return unicode(text, encoding, errors) if isinstance(text, str) else text
        return str(text)

# Instantiate compatibility module
compat = CompatibilityModule()

import MySQLdb
import configparser
import os
import itertools
from pprint import pprint
from MySQLdb.cursors import DictCursor

class GameDatabaseManager:
    def __init__(self, config_path='database.properties'):
        self.config = configparser.ConfigParser()
        self.config.read(config_path)
        self.connection = None
        self.cursor = None

    def db_connect(self, cursor_type=None):
        try:
            self.connection = MySQLdb.connect(
                host=self.config.get('Database', 'host'),
                user=self.config.get('Database', 'username'),
                passwd=self.config.get('Database', 'password'),
                db=self.config.get('Database', 'database')
            )

            if cursor_type == 'dict':
                self.cursor = self.connection.cursor(DictCursor)
            else:
                self.cursor = self.connection.cursor()

            return self.connection

        except MySQLdb.Error as e:
            print(f"Database Connection Error: {e}")
            return None

    def get_game_info(self, game_id):
        try:
            self.db_connect(cursor_type='dict')
            query = "SELECT * FROM games WHERE game_id = %s"
            self.cursor.execute(query, (game_id,))
            game_info = self.cursor.fetchone()
            return game_info

        except MySQLdb.Error as e:
            print(f"Error retrieving game info: {e}")
            return None
        finally:
            if self.connection:
                self.connection.close()

    def get_levels_from_game(self, game_id):
        try:
            self.db_connect(cursor_type='dict')
            query = "SELECT * FROM levels WHERE game_id = %s"
            self.cursor.execute(query, (game_id,))
            levels = self.cursor.fetchall()
            return levels

        except MySQLdb.Error as e:
            print(f"Error retrieving levels: {e}")
            return []
        finally:
            if self.connection:
                self.connection.close()

    def get_level_ids_from_game(self, game_id):
        try:
            self.db_connect()
            query = "SELECT level_id FROM levels WHERE game_id = %s"
            self.cursor.execute(query, (game_id,))
            level_ids = [level[0] for level in self.cursor.fetchall()]
            return level_ids

        except MySQLdb.Error as e:
            print(f"Error retrieving level IDs: {e}")
            return []
        finally:
            if self.connection:
                self.connection.close()

    def get_level_info(self, level_id):
        try:
            self.db_connect(cursor_type='dict')
            query = "SELECT * FROM levels WHERE level_id = %s"
            self.cursor.execute(query, (level_id,))
            level_info = self.cursor.fetchone()
            return level_info

        except MySQLdb.Error as e:
            print(f"Error retrieving level info: {e}")
            return None
        finally:
            if self.connection:
                self.connection.close()

    def batch_game_info_retrieval(self, game_ids):
        batch_results = {}
        for game_id in game_ids:
            game_info = self.get_game_info(game_id)
            if game_info:
                batch_results[game_id] = game_info
        return batch_results

    def generate_level_statistics(self, game_id):
        levels = self.get_levels_from_game(game_id)
        total_levels = len(levels)
        average_difficulty = sum(level['difficulty'] for level in levels) / total_levels

        return {
            'total_levels': total_levels,
            'average_difficulty': average_difficulty,
            'levels': levels
        }

def main():
    db_manager = GameDatabaseManager()

    # Example usage
    game_id = 1
    game_info = db_manager.get_game_info(game_id)
    level_info = db_manager.get_levels_from_game(game_id)

    if game_info:
        print("Game Information:")
        pprint(game_info)

    if level_info:
        print("\nLevel Information:")
        pprint(level_info)

if __name__ == "__main__":
    main()

import json
from moto.core.responses import BaseResponse

class SupportResponse(BaseResponse):
    def __init__(self):
        super().__init__()
        self.support_backend = None

    def _get_param(self, param_name, default=None):
        """
        Retrieve parameter from request with optional default value
        """
        return self.parameters.get(param_name, default)

    def describe_trusted_advisor_checks(self):
        """
        Retrieve Trusted Advisor check details
        """
        language = self._get_param('language', 'en')
        checks = self.support_backend.describe_trusted_advisor_checks(language)
        return json.dumps({
            'checks': checks,
            'ResponseMetadata': {
                'RequestId': self._get_request_id()
            }
        })

    def refresh_trusted_advisor_check(self):
        """
        Refresh specific Trusted Advisor check
        """
        check_id = self._get_param('checkId')
        result = self.support_backend.refresh_trusted_advisor_check(check_id)
        return json.dumps({
            'status': result,
            'ResponseMetadata': {
                'RequestId': self._get_request_id()
            }
        })

    def create_case(self):
        """
        Create a new support case
        """
        case_params = {
            'subject': self._get_param('subject'),
            'service_code': self._get_param('serviceCode'),
            'severity_code': self._get_param('severityCode'),
            'category_code': self._get_param('categoryCode'),
            'communication_body': self._get_param('communicationBody'),
            'attachment_set_id': self._get_param('attachmentSetId')
        }

        case = self.support_backend.create_case(**{k: v for k, v in case_params.items() if v is not None})

        return json.dumps({
            'caseId': case['caseId'],
            'ResponseMetadata': {
                'RequestId': self._get_request_id()
            }
        })

    def resolve_case(self):
        """
        Resolve an existing support case
        """
        case_id = self._get_param('caseId')
        resolution_params = {
            'resolution_status': self._get_param('resolutionStatus'),
            'resolution_details': self._get_param('resolutionDetails')
        }

        resolved_case = self.support_backend.resolve_case(
            case_id, 
            **{k: v for k, v in resolution_params.items() if v is not None}
        )

        return json.dumps({
            'case': resolved_case,
            'ResponseMetadata': {
                'RequestId': self._get_request_id()
            }
        })

    def describe_cases(self):
        """
        Retrieve support case details
        """
        case_params = {
            'case_id_list': self._get_param('caseIdList', []),
            'include_resolved_cases': self._get_param('includeResolvedCases', False),
            'language': self._get_param('language', 'en')
        }

        cases = self.support_backend.describe_cases(**case_params)

        return json.dumps({
            'cases': cases,
            'ResponseMetadata': {
                'RequestId': self._get_request_id()
            }
        })

    def _get_request_id(self):
        """
        Generate unique request identifier
        """
        import uuid
        return str(uuid.uuid4())

