import re
import calendar
from typing import List, Union, Optional, Dict, Any
from datetime import datetime, timedelta

class CronExpressionError(Exception):
    """Custom exception for cron expression parsing errors."""
    pass

class BaseField:
    def __init__(self, expr: str, min_val: int, max_val: int):
        self.expr = str(expr)
        self.min_val = min_val
        self.max_val = max_val
        self.values = self._parse_expression()

    def _parse_expression(self) -> List[int]:
        if self.expr == '*':
            return list(range(self.min_val, self.max_val + 1))

        values = set()
        for part in self.expr.split(','):
            if '-' in part:
                start, end = map(int, part.split('-'))
                values.update(range(start, end + 1))
            elif '/' in part:
                base, step = part.split('/')
                base = int(base) if base != '*' else self.min_val
                step = int(step)
                values.update(range(base, self.max_val + 1, step))
            else:
                values.add(int(part))

        return sorted(values)

    def match(self, value: int) -> bool:
        return value in self.values

    def get_next_value(self, current: int) -> Optional[int]:
        candidates = [v for v in self.values if v >= current]
        return candidates[0] if candidates else None

class WeekField(BaseField):
    def __init__(self, expr: str):
        super().__init__(expr, 0, 7)
        # Normalize Sunday as 7 or 0
        self.values = [0 if v == 7 else v for v in self.values]

class DayOfMonthField(BaseField):
    def get_next_value(self, current: int, year: int, month: int) -> Optional[int]:
        _, last_day = calendar.monthrange(year, month)
        candidates = [v for v in self.values if v <= last_day and v >= current]
        return candidates[0] if candidates else None

class CronExpression:
    def __init__(self, expr: str):
        parts = expr.split()
        if len(parts) != 5:
            raise CronExpressionError("Invalid cron expression")

        self.minute = BaseField(parts[0], 0, 59)
        self.hour = BaseField(parts[1], 0, 23)
        self.day_of_month = DayOfMonthField(parts[2], 1, 31)
        self.month = BaseField(parts[3], 1, 12)
        self.day_of_week = WeekField(parts[4])

    def match(self, dt: datetime) -> bool:
        return all([
            self.minute.match(dt.minute),
            self.hour.match(dt.hour),
            self.day_of_month.match(dt.day),
            self.month.match(dt.month),
            self.day_of_week.match(dt.weekday())
        ])

    def get_next_occurrence(self, from_dt: datetime) -> datetime:
        current = from_dt + timedelta(minutes=1)
        max_iterations = 10000

        while max_iterations > 0:
            if self.match(current):
                return current

            # Smart incrementation logic
            if not self.month.match(current.month):
                current = current.replace(
                    day=1, hour=0, minute=0, 
                    month=self._next_month(current.month)
                )
            elif not self.day_of_month.match(current.day):
                current = current.replace(
                    hour=0, minute=0, 
                    day=self.day_of_month.get_next_value(
                        current.day, current.year, current.month
                    ) or 1
                )

            current += timedelta(minutes=1)
            max_iterations -= 1

        raise CronExpressionError("Could not find next occurrence")

    def _next_month(self, current_month: int) -> int:
        return current_month + 1 if current_month < 12 else 1

def parse_cron_schedule(schedule: str) -> CronExpression:
    try:
        return CronExpression(schedule)
    except Exception as e:
        raise CronExpressionError(f"Invalid schedule: {str(e)}")

def validate_cron_expression(expr: str) -> bool:
    try:
        parse_cron_schedule(expr)
        return True
    except CronExpressionError:
        return False

import os
import tempfile
import uuid

import fixtures
from oslo_config import cfg
from oslo_policy import policy as oslo_policy
from oslo_serialization import jsonutils
import oslotest.base


class FakePolicy(oslo_policy.Policy):
    def __init__(self, rules=None):
        super(FakePolicy, self).__init__()
        self.rules = rules or {}

    def load_rules(self, force_reload=False):
        self.rules = self.rules or {}
        return self.rules


class ConfigFixture(fixtures.Fixture):
    def __init__(self, conf=None):
        super(ConfigFixture, self).__init__()
        self.conf = conf or cfg.CONF

    def setUp(self):
        super(ConfigFixture, self).setUp()
        self.conf_dir = self.useFixture(fixtures.TempDir()).path
        self.conf.set_override('config_dir', self.conf_dir)

    def conf_override(self, **kwargs):
        for k, v in kwargs.items():
            self.conf.set_override(k, v)


class EmptyPolicyFixture(fixtures.Fixture):
    def setUp(self):
        super(EmptyPolicyFixture, self).setUp()
        self.policy_file = tempfile.mkstemp()[1]
        jsonutils.dump_as_bytes({}, self.policy_file)
        self.addCleanup(os.unlink, self.policy_file)


class BaseTestCase(oslotest.base.BaseTestCase):
    def setUp(self):
        super(BaseTestCase, self).setUp()
        self.conf_fixture = self.useFixture(ConfigFixture())
        self.policy_fixture = self.useFixture(EmptyPolicyFixture())
        self.conf_override = self.conf_fixture.conf_override
        self._policy_path = self.policy_fixture.policy_file
        self._prepare_policy()

    def _prepare_policy(self):
        self.conf_override(policy_file=self._policy_path)
        policy = FakePolicy()
        oslo_policy.set_policy_defaults(policy)
        self.policy = policy

    def list_rules(self):
        return dict(self.policy.rules)

    def add_missing_default_rules(self, rules):
        current_rules = self.list_rules()
        updated_rules = current_rules.copy()

        for rule_name, rule_definition in rules.items():
            if rule_name not in current_rules:
                updated_rules[rule_name] = rule_definition

        self.policy.rules = updated_rules

    def create_default_policy_file(self, rules=None):
        rules = rules or {}
        policy_file_path = os.path.join(
            tempfile.mkdtemp(),
            f'policy-{str(uuid.uuid4())}.json'
        )
        with open(policy_file_path, 'w') as policy_file:
            jsonutils.dump(rules, policy_file)
        return policy_file_path

    def override_policy(self, rules):
        policy_file = self.create_default_policy_file(rules)
        self.conf_override(policy_file=policy_file)
        self.policy.rules = rules or {}

    def assertPolicyRuleExists(self, rule_name):
        """Verify that a specific policy rule exists."""
        current_rules = self.list_rules()
        self.assertIn(rule_name, current_rules)

    def assertPolicyRuleNotExists(self, rule_name):
        """Verify that a specific policy rule does not exist."""
        current_rules = self.list_rules()
        self.assertNotIn(rule_name, current_rules)

    def assertPolicyRuleMatches(self, rule_name, expected_rule):
        """Verify that a policy rule matches the expected definition."""
        current_rules = self.list_rules()
        self.assertIn(rule_name, current_rules)
        self.assertEqual(current_rules[rule_name], expected_rule)

    def simulate_policy_check(self, rule_name, context, target=None):
        """Simulate a policy check for testing purposes."""
        target = target or {}
        try:
            return oslo_policy.check_is_admin(rule_name, target, context)
        except oslo_policy.PolicyNotAuthorized:
            return False

#!/usr/bin/env python3
import os
import sys
import yaml
import logging
import optparse
import requests
from getpass import getpass
from keystoneclient.v3 import client as keystone_client

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s: %(message)s')
logger = logging.getLogger(__name__)

class KeyringProxy:
    def __init__(self, username, password=None):
        self.username = username
        self.password = password or self._prompt_password()

    def _prompt_password(self):
        return getpass(f"Enter password for {self.username}: ")

    def get_password(self):
        return self.password

def get_token(keystone_uri, username, password):
    try:
        auth_payload = {
            "auth": {
                "identity": {
                    "methods": ["password"],
                    "password": {
                        "user": {
                            "name": username,
                            "domain": {"id": "default"},
                            "password": password
                        }
                    }
                },
                "scope": {
                    "project": {
                        "name": "admin",
                        "domain": {"id": "default"}
                    }
                }
            }
        }
        response = requests.post(f"{keystone_uri}/auth/tokens", json=auth_payload)
        response.raise_for_status()
        return response.headers.get('X-Subject-Token')
    except requests.exceptions.RequestException as e:
        logger.error(f"Token retrieval failed: {e}")
        sys.exit(1)

def filter_resource(resources, condition=None):
    return [resource for resource in resources if condition is None or condition(resource)]

def replace_services_endpoints(keystone_client, config):
    try:
        # Delete existing endpoints
        existing_endpoints = keystone_client.endpoints.list()
        for endpoint in filter_resource(existing_endpoints):
            keystone_client.endpoints.delete(endpoint.id)
            logger.info(f"Deleted endpoint: {endpoint.id}")

        # Delete existing services
        existing_services = keystone_client.services.list()
        for service in filter_resource(existing_services):
            keystone_client.services.delete(service.id)
            logger.info(f"Deleted service: {service.id}")

        # Create new services
        for service_config in config.get('services', []):
            new_service = keystone_client.services.create(
                name=service_config['name'],
                type=service_config['type'],
                description=service_config.get('description', '')
            )
            logger.info(f"Created service: {new_service.id}")

            # Create corresponding endpoints
            for endpoint_config in service_config.get('endpoints', []):
                new_endpoint = keystone_client.endpoints.create(
                    service=new_service.id,
                    interface=endpoint_config['interface'],
                    url=endpoint_config['url'],
                    region=endpoint_config.get('region', 'RegionOne')
                )
                logger.info(f"Created endpoint: {new_endpoint.id}")

    except Exception as e:
        logger.error(f"Service and endpoint replacement failed: {e}")
        sys.exit(1)

def main():
    parser = optparse.OptionParser(usage="Usage: %prog [options] config_file")
    parser.add_option("-u", "--keystone-uri", dest="keystone_uri", 
                      help="Keystone service URI", default="http://localhost:5000")
    parser.add_option("-l", "--username", dest="username", 
                      help="Keystone admin username")

    options, args = parser.parse_args()

    if len(args) != 1:
        parser.error("Specify configuration file")

    config_file = args[0]
    if not os.path.exists(config_file):
        logger.error(f"Configuration file not found: {config_file}")
        sys.exit(1)

    try:
        with open(config_file, 'r') as f:
            config = yaml.safe_load(f)
    except yaml.YAMLError as e:
        logger.error(f"Invalid YAML configuration: {e}")
        sys.exit(1)

    keyring = KeyringProxy(options.username)
    token = get_token(options.keystone_uri, keyring.username, keyring.get_password())

    keystone = keystone_client.Client(
        token=token,
        auth_url=options.keystone_uri
    )

    replace_services_endpoints(keystone, config)
    logger.info("Services and endpoints successfully updated")

if __name__ == "__main__":
    main()

import unittest
from thrift.protocol.TSimpleJSONProtocol import TSimpleJSONProtocol
from thrift.transport.TTransport import TMemoryBuffer
from thrift.Thrift import TType
from typing import List, Dict, Set

# Thrift generated structs for testing
class SortedStruct:
    def __init__(self, id: int = 0, name: str = "", tags: Dict[str, str] = None):
        self.id = id
        self.name = name
        self.tags = tags or {}

    def __repr__(self):
        return f"SortedStruct(id={self.id}, name='{self.name}', tags={self.tags})"

class SortedSetStruct:
    def __init__(self, unique_ids: Set[int] = None):
        self.unique_ids = unique_ids or set()

    def __repr__(self):
        return f"SortedSetStruct(unique_ids={self.unique_ids})"

class NegativeId:
    def __init__(self, negative_val: int = -1):
        self.negative_val = negative_val

class ThriftSerializationTest(unittest.TestCase):
    def writeToJSON(self, struct):
        """Serialize Thrift struct to JSON"""
        transport = TMemoryBuffer()
        protocol = TSimpleJSONProtocol(transport)
        struct.write(protocol)
        return transport.getvalue().decode('utf-8')

    def readStructFromJSON(self, struct_type, json_data):
        """Deserialize JSON to Thrift struct"""
        transport = TMemoryBuffer(json_data.encode('utf-8'))
        protocol = TSimpleJSONProtocol(transport)
        struct = struct_type()
        struct.read(protocol)
        return struct

    def test_sorted_map_serialization(self):
        """Test map serialization with sorted keys"""
        struct = SortedStruct(
            id=42, 
            name="Test Struct", 
            tags={"zebra": "animal", "apple": "fruit", "cat": "mammal"}
        )
        json_output = self.writeToJSON(struct)

        # Verify keys are sorted
        expected_order = '{"id":42,"name":"Test Struct","tags":{"apple":"fruit","cat":"mammal","zebra":"animal"}}'
        self.assertEqual(json_output, expected_order)

    def test_sorted_set_serialization(self):
        """Test set serialization with sorted elements"""
        struct = SortedSetStruct(
            unique_ids={5, 2, 8, 1, 3}
        )
        json_output = self.writeToJSON(struct)

        # Verify set elements are sorted
        expected_order = '{"unique_ids":[1,2,3,5,8]}'
        self.assertEqual(json_output, expected_order)

    def test_struct_roundtrip_serialization(self):
        """Test complete serialization and deserialization roundtrip"""
        original_struct = SortedStruct(
            id=123, 
            name="Roundtrip Test", 
            tags={"python": "language", "thrift": "serialization"}
        )
        json_data = self.writeToJSON(original_struct)
        reconstructed_struct = self.readStructFromJSON(SortedStruct, json_data)

        # Verify struct contents remain identical
        self.assertEqual(original_struct.id, reconstructed_struct.id)
        self.assertEqual(original_struct.name, reconstructed_struct.name)
        self.assertEqual(original_struct.tags, reconstructed_struct.tags)

    def test_default_field_initialization(self):
        """Test default field values for structs"""
        default_struct = SortedStruct()
        self.assertEqual(default_struct.id, 0)
        self.assertEqual(default_struct.name, "")
        self.assertEqual(default_struct.tags, {})

    def test_negative_value_serialization(self):
        """Test serialization of negative values"""
        negative_struct = NegativeId()
        json_output = self.writeToJSON(negative_struct)

        # Verify negative value is preserved
        expected_output = '{"negative_val":-1}'
        self.assertEqual(json_output, expected_output)

